    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    # If a is empty, return empty list
    if not a:
        return []

    # If b is empty, merge and return a
    if not b:
        return merge(a)

    # Merge both lists of intervals
    a_merged = merge(a)
    b_merged = merge(b)

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_ranges = [(a_start, a_end)]

        for b_start, b_end in b_merged:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    new_ranges.append((curr_start, curr_end))
                else:
                    # There is overlap, keep the parts that don't overlap
                    if curr_start < b_start:
                        new_ranges.append((curr_start, b_start))
                    if curr_end > b_end:
                        new_ranges.append((b_end, curr_end))
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge the result to combine touching intervals
    result = merge(result)

    # Convert tuples back to lists
    return [[start, end] for start, end in result]


def merge(intervals):
    """Merge overlapping or touching intervals"""
    if not intervals:
        return []

    # Sort intervals by start point, then by end point
    sorted_intervals = sorted(intervals)

    merged = [sorted_intervals[0]]

    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        # If current interval overlaps or touches the last one, merge them
        if current_start <= last_end:
            merged[-1] = (last_start, max(last_end, current_end))
        else:
            merged.append((current_start, current_end))

    return merged

